def solve_langford(n, partial=None):
    length = 2 * n
    seq = [0] * length

    if partial:
        for pos, val in partial.items():
            seq[pos] = val

    used = [False] * (n + 1)

    # Mark used values from partial
    if partial:
        for pos, val in partial.items():
            if used[val]:
                return None  # Conflict
            used[val] = True

    def backtrack(pos):
        if pos == length:
            return True

        if seq[pos] != 0:
            return backtrack(pos + 1)

        for v in range(1, n + 1):
            if used[v]:
                continue

            gap = v + 1
            other = pos + gap

            if other >= length:
                continue

            if seq[other] != 0:
                continue

            # Place v at pos and other
            seq[pos] = v
            seq[other] = v
            used[v] = True

            if backtrack(pos + 1):
                return True

            # Undo
            seq[pos] = 0
            seq[other] = 0
            used[v] = False

        return False

    if backtrack(0):
        return seq
    return None

